	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		PerformanceReview
	 */
		public PerformanceReview createPerformanceReview( CreatePerformanceReviewCommand command ) {

		PerformanceReview entity = new PerformanceReview();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPerformanceReviewId( command.getPerformanceReviewId() );
            entity.setReviewNumber( command.getReviewNumber() );
            entity.setReviewDate( command.getReviewDate() );
            entity.setReviewerComments( command.getReviewerComments() );
            entity.setRating( command.getRating() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of PerformanceReview {0} ", entity.toString() );

		return entity;
	}

